// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Recorder r;

    function setUp() public {
        c = new MyContract();
        r = new Recorder();
    }

    function testFuzz_property(uint256 amount, bool shouldFail) public {
        vm.assume(amount > 0);
        r.setShouldFail(shouldFail);
        vm.deal(address(c), amount);

        bool ok;
        // test contract is the deployer, hence owner of c
        try c.sendTo(address(r), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: a sendTo that completes without reverting must have
        // actually delivered exactly `amount` wei to the receiver.
        assertTrue(!ok || r.received() == amount, "successful sendTo must deliver amount");
    }
}

contract Recorder {
    bool public shouldFail;
    uint256 public received;

    function setShouldFail(bool f) external { shouldFail = f; }

    receive() external payable {
        received += msg.value;
        if (shouldFail) revert();
    }
}
